create extension if not exists pgcrypto;
create or replace function public.set_updated_at() returns trigger language plpgsql as $$ begin new.updated_at = timezone('utc', now()); return new; end; $$;
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, full_name text, avatar_url text, headline text, location text, phone text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.companies (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, name text not null, website text, industry text, location text, company_size text, contact_name text, contact_email text, notes text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(user_id,name));
create table public.resumes (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, name text not null, category text, version text, file_path text not null, file_size bigint, mime_type text not null default 'application/pdf' check(mime_type='application/pdf'), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.applications (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, company_id uuid references public.companies(id) on delete set null, resume_id uuid references public.resumes(id) on delete set null, job_title text not null, company_name text not null, company_website text, company_logo text, job_description text, job_location text, work_type text check(work_type is null or work_type in ('Remote','Hybrid','On-site')), employment_type text, salary_min numeric(12,2), salary_max numeric(12,2), job_url text, application_date date, application_deadline date, status text not null default 'Saved' check(status in ('Saved','Applied','Assessment','Interview','Offer','Rejected','Withdrawn')), priority text not null default 'Medium' check(priority in ('Low','Medium','High')), contact_person text, contact_email text, notes text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), check(salary_min is null or salary_max is null or salary_max>=salary_min));
create table public.interviews (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, application_id uuid not null references public.applications(id) on delete cascade, scheduled_at timestamptz not null, duration_minutes integer, interview_type text, meeting_link text, location text, interviewer_name text, interviewer_email text, preparation_notes text, status text not null default 'Scheduled' check(status in ('Scheduled','Completed','Cancelled','Rescheduled')), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.follow_up_tasks (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, application_id uuid references public.applications(id) on delete cascade, title text not null, notes text, due_at timestamptz not null, completed_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.notifications (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, title text not null, message text not null, type text not null default 'info', read_at timestamptz, link text, created_at timestamptz not null default now());
create table public.activity_logs (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, entity_type text not null, entity_id uuid, action text not null, details jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
create index applications_user_status_idx on public.applications(user_id,status); create index applications_user_date_idx on public.applications(user_id,application_date desc); create index interviews_user_scheduled_idx on public.interviews(user_id,scheduled_at); create index followups_user_due_idx on public.follow_up_tasks(user_id,due_at); create index notifications_user_created_idx on public.notifications(user_id,created_at desc); create index activity_logs_user_created_idx on public.activity_logs(user_id,created_at desc);
alter table public.profiles enable row level security; alter table public.companies enable row level security; alter table public.resumes enable row level security; alter table public.applications enable row level security; alter table public.interviews enable row level security; alter table public.follow_up_tasks enable row level security; alter table public.notifications enable row level security; alter table public.activity_logs enable row level security;
create policy profiles_select_own on public.profiles for select to authenticated using(id=auth.uid()); create policy profiles_insert_own on public.profiles for insert to authenticated with check(id=auth.uid()); create policy profiles_update_own on public.profiles for update to authenticated using(id=auth.uid()) with check(id=auth.uid());
create policy companies_all_own on public.companies for all to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid()); create policy resumes_all_own on public.resumes for all to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid()); create policy applications_all_own on public.applications for all to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid()); create policy interviews_all_own on public.interviews for all to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid()); create policy followups_all_own on public.follow_up_tasks for all to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid()); create policy notifications_all_own on public.notifications for all to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid()); create policy activity_logs_select_own on public.activity_logs for select to authenticated using(user_id=auth.uid()); create policy activity_logs_insert_own on public.activity_logs for insert to authenticated with check(user_id=auth.uid());
create trigger profiles_updated_at before update on public.profiles for each row execute function public.set_updated_at(); create trigger companies_updated_at before update on public.companies for each row execute function public.set_updated_at(); create trigger resumes_updated_at before update on public.resumes for each row execute function public.set_updated_at(); create trigger applications_updated_at before update on public.applications for each row execute function public.set_updated_at(); create trigger interviews_updated_at before update on public.interviews for each row execute function public.set_updated_at(); create trigger followups_updated_at before update on public.follow_up_tasks for each row execute function public.set_updated_at();
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path='' as $$ begin insert into public.profiles(id,full_name) values(new.id,coalesce(new.raw_user_meta_data->>'full_name','')) on conflict(id) do nothing; return new; end; $$; create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('applytrack-resumes','applytrack-resumes',false,5242880,array['application/pdf']) on conflict(id) do nothing;
create policy resume_storage_select_own on storage.objects for select to authenticated using(bucket_id='applytrack-resumes' and (storage.foldername(name))[1]=auth.uid()::text); create policy resume_storage_insert_own on storage.objects for insert to authenticated with check(bucket_id='applytrack-resumes' and (storage.foldername(name))[1]=auth.uid()::text); create policy resume_storage_update_own on storage.objects for update to authenticated using(bucket_id='applytrack-resumes' and (storage.foldername(name))[1]=auth.uid()::text) with check(bucket_id='applytrack-resumes' and (storage.foldername(name))[1]=auth.uid()::text); create policy resume_storage_delete_own on storage.objects for delete to authenticated using(bucket_id='applytrack-resumes' and (storage.foldername(name))[1]=auth.uid()::text);
